// Some portions generated by Co-Pilot
import { fireEvent, render, screen } from "@testing-library/react";
import { describe, expect, it, vi } from "vitest";
import BecomeSustainerClient from "../BecomeSustainerClient";

vi.mock("next-intl", async () => {
  const actual = await vi.importActual<typeof import("next-intl")>("next-intl");
  const messages = (await import("@/../locales/en.json")).default;
  return {
    ...actual,
    useTranslations: (namespace: "ModernPages.sustainer" | "NavBar") =>
      actual.createTranslator({ locale: "en", messages, namespace }),
  };
});

vi.mock("@/components/HubspotForm", () => ({
  default: ({
    portalId,
    formId,
    onFormSubmit,
  }: {
    portalId: string;
    formId: string;
    onFormSubmit: () => void;
  }) => (
    <button data-portal={portalId} data-form={formId} onClick={onFormSubmit}>
      Simulate hosted form callback
    </button>
  ),
}));

describe("Corporate sustainer enquiry", () => {
  it("preserves the production HubSpot form and related destinations", () => {
    render(<BecomeSustainerClient />);
    expect(
      screen.getByRole("heading", {
        level: 1,
        name: "Become a Corporate Sustainer",
      }),
    ).toBeInTheDocument();
    const form = screen.getByRole("button", {
      name: "Simulate hosted form callback",
    });
    expect(form).toHaveAttribute("data-portal", "5413615");
    expect(form).toHaveAttribute(
      "data-form",
      "6e3e994e-5bc8-4a6e-91b3-d3f331b69402",
    );
    expect(
      screen.getByRole("link", { name: "Become a Corporate Sustainer" }),
    ).toHaveAttribute("href", "/sustainers");
    expect(
      screen.getByRole("link", { name: "Become a Member" }),
    ).toHaveAttribute("href", "/members");
  });

  it("announces the original form submission callback without unmounting the form", () => {
    render(<BecomeSustainerClient />);
    fireEvent.click(
      screen.getByRole("button", { name: "Simulate hosted form callback" }),
    );
    expect(screen.getByRole("status")).toHaveTextContent(
      "Thank you for your support",
    );
    expect(
      screen.getByRole("button", { name: "Simulate hosted form callback" }),
    ).toBeInTheDocument();
  });
});
